        "quelle_url": "https://www.bgbl.de/xaver/bgbl/start.xav?startbk=Bundesanzeiger_BGBl&jumpTo=bgbl113s0285.pdf",
        "hinweis": "Eine vom Arbeitgeber oder auf seine Veranlassung gestellte Mahlzeit bis 60 Euro wird mit dem amtlichen Sachbezugswert bewertet und gar nicht angesetzt, wenn der Arbeitnehmer für den Tag eine Verpflegungspauschale geltend machen könnte (§ 8 Abs. 2 Satz 9 EStG); die Pauschale wird dann gekürzt. Maßgeblich ist der Preis einschließlich Umsatzsteuer und Getränken; teurere Mahlzeiten sind mit dem vollen Preis Arbeitslohn (BMF-Schreiben vom 25. November 2020, BStBl I S. 1228, Rz. 61 bis 63). Bleibt ein Sachbezugswert zu versteuern, ist eine Pauschalierung mit 25 Prozent möglich (§ 40 Abs. 2 Satz 1 Nr. 1a EStG)."
