        "rechtsgrundlage": "§ 3 Nr. 21 Satz 1, 3 und 6 EStG, eingefügt durch Artikel 1 Nr. 1 des Aktivrentengesetzes vom 22. Dezember 2025, in Kraft seit 1. Januar 2026 (Artikel 4)",
        "quelle_url": "https://www.recht.bund.de/bgbl/1/2025/361/VO.html",
        "hinweis": "Für jeden Kalendermonat ohne die Voraussetzungen mindert sich der Betrag um ein Zwölftel, im Lohnsteuerabzug gilt er zeitanteilig; nach der FAQ des BMF sind das 2.000 Euro je Monat ohne Übertrag in andere Monate (ohne Bindungswirkung). Gilt ab dem Monat nach Erreichen der Regelaltersgrenze (§ 35 Satz 2 oder § 235 SGB VI) für Arbeitslohn aus einer Beschäftigung, für die der Arbeitgeber Beiträge nach § 168 Abs. 1 Nr. 1 oder 1d oder Abs. 3, § 172 Abs. 1 oder § 172a SGB VI zahlt, also nicht für Minijobs, Selbständige und Beamte. Eine Altersrente muss nicht bezogen werden. Nicht genutzte Monatsbeträge verfallen (FAQ des BMF zur Aktivrente, Stand 25. Juni 2026). In Steuerklasse VI gilt der Freibetrag nur, wenn der Arbeitnehmer bestätigt, dass er ihn nicht schon in einem anderen Dienstverhältnis nutzt (§ 3 Nr. 21 Satz 4 EStG). Beitragspflichtig in der Sozialversicherung bleibt der Lohn trotzdem (§ 1 Abs. 1 Satz 1 Nr. 1 SvEV)."
